// ===== FIX PROBLEM 1 & 7: CHARACTER DATA FLOW =====
// Merge character data from GetChar node and pass it forward

const gridData = $input.all()[0].json;
const characterData = $input.all()[1].json;
const formData = $('ParseFormData').first().json;

// Extract complete character physical details
const characterPhysical = characterData.characterPhysical;
const characterConsistency = characterData.consistencyChecklist;

// Build filled character description (no placeholders!)
const filledCharacterDescription = `A ${characterPhysical.coreIdentity.exactAge}-year-old ${characterPhysical.coreIdentity.gender}, ${characterPhysical.coreIdentity.ethnicitySpecific} ethnicity. ${characterPhysical.facialStructure.faceShape} face with ${characterPhysical.facialStructure.eyes.shape} ${characterPhysical.facialStructure.eyes.color} eyes, ${characterPhysical.hairSpecification.colorExact} hair (${characterPhysical.hairSpecification.lengthMeasurement}, ${characterPhysical.hairSpecification.currentStyle}). ${characterPhysical.bodySpecification.height} tall, ${characterPhysical.bodySpecification.buildType} build. Skin tone: ${characterPhysical.skinSpecification.baseColor}, ${characterPhysical.skinSpecification.undertone} undertone. Wearing ${characterPhysical.stylePresentation.clothingExact}.`;

console.log('✅ Character Description:', filledCharacterDescription);

// ===== FIX PROBLEM 2 & 3: MODEL SELECTION & VIDEO CALCULATION =====
const totalDuration = formData.duration; // e.g., 30
const platform = formData.platform;

// Select model based on duration
let videoModel, modelMaxDuration;
if (totalDuration <= 24) {
  videoModel = 'veo-3.1';
  modelMaxDuration = 8;
} else {
  videoModel = 'seedance-1-5-pro';
  modelMaxDuration = 12;
}

// Calculate total scenes needed
const totalScenes = Math.ceil(totalDuration / modelMaxDuration);
const sceneDuration = Math.floor(totalDuration / totalScenes);

console.log('✅ Model Selection:', videoModel);
console.log('✅ Calculated Scenes:', totalScenes, '×', sceneDuration, 'seconds');

// ===== FIX PROBLEM 10: RESOURCE CALCULATION =====
const resourceRequirements = {
  totalImagesNeeded: totalScenes,
  totalVideoClipsNeeded: totalScenes,
  estimatedImageGenerationTime: totalScenes * 60, // 1 min per image
  estimatedVideoGenerationTime: totalScenes * 120, // 2 min per video
  estimatedTotalTime: (totalScenes * 60) + (totalScenes * 120) + 30 // images + videos + concat
};

console.log('✅ Resources:', resourceRequirements);

return [{
  json: {
    // Character data (FILLED, no placeholders)
    characterImageUrl: characterData.characterImageUrl,
    characterPhysical: characterPhysical,
    characterConsistency: characterConsistency,
    characterDescription: filledCharacterDescription,

    // Product data
    productImages: gridData.images,
    productInfo: gridData.product,
    ugcCreatorProfile: gridData.ugcCreatorProfile,
    videoProductionMetadata: gridData.videoProductionMetadata,

    // Form data
    productName: formData.productName,
    productDescription: formData.productDescription,
    targetAudience: formData.targetAudience,
    ugcStyleDetails: formData.ugcStyleDetails,
    additionalNotes: formData.additionalNotes,
    platform: formData.platform,
    aspectRatio: formData.aspectRatio,

    // Video configuration
    videoConfig: {
      totalDuration,
      totalScenes,
      sceneDuration,
      videoModel,
      modelMaxDuration,
      aspectRatio: formData.aspectRatio,
      platform
    },

    // Resource requirements
    resourceRequirements,

    timestamp: new Date().toISOString(),
    status: 'data_prepared_for_gemini',
    progress: 45
  }
}];

