// Parse Gemini scene prompts
const geminiResponse = $input.first().json;
let rawText = geminiResponse.content?.parts?.[0]?.text || geminiResponse.text || JSON.stringify(geminiResponse);
let cleanText = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
let sceneData = JSON.parse(cleanText);

if (!sceneData.scenes || sceneData.scenes.length === 0) {
  throw new Error('No scenes generated');
}

console.log('✅ Scenes Parsed:', sceneData.scenes.length);

// Verify character description is in prompts
sceneData.scenes.forEach(scene => {
  if (!scene.nanoPrompt.includes('year-old')) {
    console.warn('⚠️ Scene', scene.sceneNumber, 'missing character baseline!');
  }
});

const previousData = $('Prepare Data & Calculate').first().json;

return [{
  json: {
    scenes: sceneData.scenes,
    characterReference: sceneData.characterReference,
    productIntegration: sceneData.productIntegration,
    videoConfig: previousData.videoConfig,
    productImages: previousData.productImages,
    characterImageUrl: previousData.characterImageUrl,
    timestamp: new Date().toISOString(),
    status: 'scene_prompts_ready',
    progress: 55
  }
}];

// ===== FIX PROBLEM 9: CROP 2x2 GRID INTO 4 CELLS =====
// This is a placeholder - actual image cropping would need ImageMagick/Sharp
// For now, we'll reference the full grid and add cropping instructions to prompts

const sceneData = $input.first().json;
const gridImageUrl = sceneData.productImages.generatedGrid;

// Grid cell mapping (for future cropping)
const gridCells = {
  0: { name: 'top-left', crop: '0x0+50%x50%', description: 'Front view' },
  1: { name: 'top-right', crop: '50%x0+50%x50%', description: '45° angle' },
  2: { name: 'bottom-left', crop: '0x50%+50%x50%', description: 'Top-down' },
  3: { name: 'bottom-right', crop: '50%x50%+50%x50%', description: 'Macro detail' }
};

// Map scenes to grid cells
const scenesWithProducts = sceneData.scenes.map((scene, index) => {
  if (scene.productVisible && index > 0) {
    const cellIndex = (index - 1) % 4; // Scene 1 → cell 0, Scene 2 → cell 1, etc.
    const cell = gridCells[cellIndex];
    return {
      ...scene,
      productCell: cell,
      productImageInstruction: `Show ${sceneData.productIntegration.productName} from ${cell.description} angle (${cell.name} cell of 2x2 grid)`
    };
  }
  return scene;
});

console.log('✅ Grid cells mapped to scenes');

return [{
  json: {
    ...sceneData,
    scenes: scenesWithProducts,
    gridImageUrl,
    gridCells,
    status: 'grid_cells_mapped',
    progress: 58
  }
}];

// Split scenes for loop processing
const sceneData = $input.first().json;
const scenes = sceneData.scenes;

const output = scenes.map(scene => ({
  json: {
    currentScene: scene,
    characterReference: sceneData.characterReference,
    productIntegration: sceneData.productIntegration,
    videoConfig: sceneData.videoConfig,
    gridImageUrl: sceneData.gridImageUrl,
    nanoBananaConfig: {
      model: 'nano-banana-pro',
      aspectRatio: scene.technicalSpecs.aspectRatio,
      resolution: '2K',
      outputFormat: 'png'
    },
    totalScenes: scenes.length
  }
}));

console.log('✅ Split into', output.length, 'scenes for generation');
return output;

// Extract scene image URL
const kieResponse = $json;
const sceneContext = $('Split Scenes').item.json;

if (kieResponse.data.state !== 'success') {
  throw new Error('Scene image failed');
}

const resultJson = JSON.parse(kieResponse.data.resultJson);
const sceneImageUrl = resultJson.resultUrls[0];

const scene = sceneContext.currentScene;

console.log('✅ Scene', scene.sceneNumber, 'image:', sceneImageUrl);

return [{
  json: {
    sceneNumber: scene.sceneNumber,
    sceneType: scene.type,
    duration: scene.duration,
    startTime: scene.startTime,
    endTime: scene.endTime,
    productVisible: scene.productVisible,
    imageUrl: sceneImageUrl,
    script: scene.script,
    videoModel: sceneContext.videoConfig.videoModel,
    modelMaxDuration: sceneContext.videoConfig.modelMaxDuration,
    technicalSpecs: scene.technicalSpecs,
    timestamp: new Date().toISOString(),
    status: 'scene_image_ready'
  }
}];

// Aggregate all scene images, prepare for video generation
const allScenes = $input.all().map(item => item.json);
allScenes.sort((a, b) => a.sceneNumber - b.sceneNumber);

console.log('✅ All', allScenes.length, 'scene images ready');

const videoModel = allScenes[0].videoModel;
const modelMaxDuration = allScenes[0].modelMaxDuration;

return [{
  json: {
    sceneImages: allScenes,
    videoConfig: {
      model: videoModel,
      maxDuration: modelMaxDuration,
      totalScenes: allScenes.length
    },
    timestamp: new Date().toISOString(),
    status: 'ready_for_video_generation',
    progress: 70
  }
}];

// ===== FIX PROBLEM 5: VIDEO GENERATION LOOP =====
// Split scene images for video generation
const data = $input.first().json;
const scenes = data.sceneImages;

const output = scenes.map(scene => ({
  json: {
    sceneNumber: scene.sceneNumber,
    imageUrl: scene.imageUrl,
    duration: scene.duration,
    script: scene.script,
    videoModel: data.videoConfig.model,
    modelMaxDuration: data.videoConfig.maxDuration,
    videoPayload: {
      model: data.videoConfig.model,
      input: {
        image_url: scene.imageUrl,
        duration: scene.duration,
        prompt: scene.script // Optional: some models accept text prompts
      }
    }
  }
}));

console.log('✅ Prepared', output.length, 'scenes for video generation');
return output;

// ===== VIDEO GENERATION API CALL (PLACEHOLDER) =====
// TODO: Replace with actual video generation API

const scene = $json;

console.log('⏸️ VIDEO GENERATION PLACEHOLDER');
console.log('   Model:', scene.videoModel);
console.log('   Scene:', scene.sceneNumber);
console.log('   Image:', scene.imageUrl);
console.log('   Duration:', scene.duration, 'seconds');
console.log('');
console.log('📋 TODO: Implement Video Generation API');
console.log('   IF model == "veo-3.1":');
console.log('      POST https://api.veo.ai/v1/generate');
console.log('      Body: { image_url, duration, prompt }');
console.log('   ELSE IF model == "seedance-1-5-pro":');
console.log('      POST https://api.seedance.ai/v1/generate');
console.log('      Body: { image_url, duration }');
console.log('');
console.log('🎬 Expected Response:');
console.log('   { "taskId": "abc123", "status": "processing" }');
console.log('');
console.log('⏳ Then: Wait 2 minutes → GET result → Extract video URL');

// For now, return mock data
return [{
  json: {
    ...scene,
    videoTaskId: 'PLACEHOLDER_' + scene.sceneNumber,
    videoStatus: 'placeholder_not_implemented',
    placeholderNote: 'Implement video API call here'
  }
}];

// ===== FIX PROBLEM 6: FFMPEG CONCATENATION =====
// TODO: Implement actual FFmpeg concatenation

const videoResults = $input.all().map(item => item.json);
videoResults.sort((a, b) => a.sceneNumber - b.sceneNumber);

console.log('⏸️ FFMPEG CONCATENATION PLACEHOLDER');
console.log('   Video clips:', videoResults.length);
console.log('');
console.log('📋 TODO: Implement FFmpeg');
console.log('   1. Download all video URLs');
console.log('   2. Create filelist.txt:');
videoResults.forEach((v, i) => {
  console.log(`      file 'scene${i}.mp4'`);
});
console.log('   3. Run FFmpeg:');
console.log('      ffmpeg -f concat -safe 0 -i filelist.txt -c copy final_video.mp4');
console.log('   4. Upload final_video.mp4 to Kie.ai or Supabase Storage');
console.log('   5. Return final video URL');

return [{
  json: {
    videoClips: videoResults,
    finalVideoUrl: null,
    status: 'ffmpeg_pending',
    progress: 90,
    placeholderNote: 'Implement FFmpeg concatenation',
    implementationSteps: [
      'Download video clips',
      'Create concat file',
      'Run ffmpeg command',
      'Upload final video',
      'Return URL'
    ]
  }
}];

// ===== SUPABASE UPLOAD (PLACEHOLDER) =====
const data = $input.first().json;

console.log('⏸️ SUPABASE UPLOAD PLACEHOLDER');
console.log('');
console.log('📋 TODO: Upload to Supabase Storage');
console.log('   1. POST final_video.mp4 to Supabase Storage');
console.log('   2. UPDATE video_jobs table:');
console.log('      SET status = "completed", video_url = <url>, progress = 100');

return [{
  json: {
    success: false,
    status: 'upload_pending',
    progress: 95,
    placeholderNote: 'Implement Supabase upload + database update'
  }
}];
